'use strict';
const R=Rules,C=CATALOG,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={F:'Força',H:'Habilidade',R:'Resistência',A:'Armadura',PdF:'Poder de Fogo'},cats={vantagem:'Vantagens',desvantagem:'Desvantagens',unica:'Vantagens únicas',pericia:'Perícias',especializacao:'Especializações',magia:'Magias',kit:'Kits',poder:'Poderes de kit',criatura:'Criaturas',regra:'Outras regras'};
const nav=[['resumo','◈','Visão geral'],['personagem','♙','Personagem'],['poderes','✧','Vantagens e perícias'],['magias','✦','Magias e kits'],['inventario','▣','Equipamentos'],['sessao','⚄','Mesa de jogo'],['biblioteca','▤','Biblioteca'],['ajustes','⚙','Campanha e ajustes']];
let state={characters:[],selected:null},view='resumo',filter={query:'',category:'vantagem',book:'3d&tManualbasico',page:0},lib={query:'',book:'',page:0},tab='lista',saveTimer,saveChain=Promise.resolve(),lastSave='Salvamento automático',storageBlocked=false;
const ch=()=>state.characters.find(c=>c.id===state.selected)||state.characters[0];
const bookTitle=id=>C.books.find(b=>b.id===id)?.title||'Regra personalizada';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4800)}
function persisted(){return {version:2,characters:state.characters,selected:state.selected,audit:editHistory.serialize()}}
function save(changedKey=null){R.calculate(ch());if(historyReady){editHistory.record(state.characters,editLabel,changedKey?{id:ch().id,key:changedKey}:null);updateHistoryButtons()}ch().updatedAt=new Date().toISOString();lastSave='Salvando…';updateSaveLabel();clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,600)}
async function flushSave(){clearTimeout(saveTimer);if(storageBlocked)return;const snapshot=JSON.stringify(persisted());saveChain=saveChain.catch(()=>{}).then(async()=>{if(window.desktop)await desktop.save(snapshot);else{const old=localStorage.getItem('forja-3det');if(old)localStorage.setItem('forja-3det-backup',old);localStorage.setItem('forja-3det',snapshot)}lastSave='Todas as alterações salvas';updateSaveLabel()}).catch(e=>{lastSave='Falha ao salvar — exporte um backup';updateSaveLabel();toast(e.message)});return saveChain}
function updateSaveLabel(){const el=$('#save-status');if(el)el.textContent=lastSave}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">SEU UNIVERSO, SUAS HISTÓRIAS</div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function field(label,key,value,type='text',extra=''){return `<div ${extra}><label for="f-${key}">${label}</label><input id="f-${key}" data-field="${key}" type="${type}" value="${esc(value)}" ${type==='number'?`step="${key.startsWith('modifiers.')?'any':'1'}"`:''}></div>`}
function area(label,key,value){return `<div><label for="f-${key}">${label}</label><textarea id="f-${key}" data-field="${key}">${esc(value)}</textarea></div>`}
function opts(values,value){return values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}" ${value===(Array.isArray(v)?v[0]:v)?'selected':''}>${esc(Array.isArray(v)?v[1]:v)}</option>`).join('')}
function select(label,key,values,value){return `<div><label for="f-${key}">${label}</label><select id="f-${key}" data-field="${key}">${opts(values,value)}</select></div>`}
function btn(action,label,cls='',data=''){return `<button class="${cls}" data-action="${action}" ${data}>${label}</button>`}
function empty(text,action,label){return `<div class="empty"><div style="font-size:28px">✧</div><p>${text}</p>${action?btn(action,label,'primary'):''}</div>`}
function render(){let c=ch(),s=R.calculate(c);patchApp(`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">F</div><div><strong>FORJA</strong><small>3D&T ALPHA</small></div></div><div><div class="eyebrow side-label">ESPAÇO DO HERÓI</div><nav class="nav" aria-label="Navegação principal">${nav.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-symbol">${icon}</span>${label}</button>`).join('')}</nav></div><div><div class="eyebrow side-label">MEUS PERSONAGENS · ${state.characters.length}</div><div class="roster">${state.characters.map(x=>`<button data-character="${x.id}" class="${x.id===c.id?'selected':''}">◈ &nbsp;${esc(x.name||'Sem nome')}</button>`).join('')}</div>${btn('new','+ Novo personagem','ghost small','style="width:100%;margin-top:8px"')}</div><div class="sidebar-bottom"><span class="dot"></span> ${C.localAvailable?'Seu acervo está offline':'Acervo local não configurado'}<br>${C.localAvailable?C.books.length+' livros · '+C.pageCount.toLocaleString('pt-BR')+' páginas':'Consulte o README para importar'}<br><span id="save-status">${lastSave}</span></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Meus personagens &nbsp; / &nbsp; <strong>${esc(c.name)}</strong></span><div class="actions">${btn('undo','↶','small',`aria-label="Desfazer alteração" title="Desfazer" ${editHistory.undo.length?'':'disabled'}`)}${btn('redo','↷','small',`aria-label="Refazer alteração" title="Refazer" ${editHistory.redo.length?'':'disabled'}`)}${btn('import','Importar','ghost small')}${btn('export','↗ Compartilhar ficha','small')}${btn('pdf','↓ PDF','primary small')}</div></header><div class="content">${({resumo:summary,personagem:character,poderes:powers,magias:magic,inventario:inventory,sessao:session,biblioteca:library,ajustes:settings,modificadores:bonusView,historico:historyView})[view](c,s)}</div></main></div>`)}
function attributes(c,s,editable=true){return `<div class="attribute-grid">${R.attrs.map(k=>`<div class="attr"><div class="symbol">${names[k]}</div><strong>${s.attrs[k]}</strong><small>${k}${c.modifiers[k]||s.attrs[k]!==c.attrs[k]?` · base ${c.attrs[k]}`:''}</small>${editable?`<div class="stepper">${btn('attr','−','',`data-key="${k}" data-delta="-1" aria-label="Diminuir ${names[k]}"`)}<input aria-label="${names[k]} base" data-attr="${k}" type="number" min="0" max="${R.MAX}" value="${c.attrs[k]}">${btn('attr','+','',`data-key="${k}" data-delta="1" aria-label="Aumentar ${names[k]}"`)}</div>`:''}</div>`).join('')}</div>`}
function resources(c,s){return `<div class="resource-grid">${[['PV','Pontos de Vida',s.pv,s.currentPV,''],['PM','Pontos de Magia',s.pm,s.currentPM,'magic']].map(([k,n,max,current,cl])=>`<div class="resource ${cl}"><label>${n}</label><strong>${current}</strong><span class="muted"> / ${max}</span><div class="progress"><div style="width:${max?current/max*100:0}%"></div></div><div class="controls">${btn('resource','−','small',`data-key="${k}" data-delta="-1" aria-label="Gastar 1 ${k}"`)}<input aria-label="${k} atuais" data-resource="${k}" type="number" min="0" max="${max}" value="${current}">${btn('resource','+','small',`data-key="${k}" data-delta="1" aria-label="Recuperar 1 ${k}"`)}</div></div>`).join('')}</div>`}
function validation(s){return s.warnings.length?s.warnings.slice(0,10).map(w=>`<div class="warn">${esc(w)}</div>`).join('')+(s.warnings.length>10?`<p>Mais ${s.warnings.length-10} opções aguardam conferência.</p>`:''):`<div class="okay">✓ Orçamento e limites numéricos conferidos.</div>`}
function summary(c,s){return heading('Toda lenda começa aqui.','Dê forma ao seu personagem. A próxima aventura é sua.',`<span class="chip green">${c.phase==='criacao'?'EM CRIAÇÃO':'EM AVENTURA'} · ${esc(c.scale)}</span>`)+`<div class="grid hero-grid"><div class="panel identity"><div class="avatar">${c.portrait?`<img alt="Retrato do personagem" src="${c.portrait}">`:'♙'}</div><div><span class="chip green">3D&T ALPHA</span><h2>${esc(c.name)}</h2><p>${esc(c.concept||'Um herói à espera de uma história.')}</p>${btn('identity','Editar identidade','ghost small')}</div></div><div class="panel score"><div class="eyebrow">PONTOS DE PERSONAGEM</div><div class="score-num">${s.spent}<span> / ${s.available}</span></div><div class="progress"><div style="width:${Math.min(100,Math.max(0,s.spent/Math.max(1,s.available)*100))}%"></div></div><small>${s.remaining>=0?`${s.remaining} pontos disponíveis`:`${-s.remaining} pontos acima do orçamento`}</small></div></div><div class="grid hero-grid section-gap"><div><section class="panel"><div class="panel-head"><h2>Características</h2><span class="chip">1 PONTO POR NÍVEL</span></div>${attributes(c,s)}<p class="hint">Valores incluem efeitos ativos. ${c.ruleMode==='free'?'Modo livre.':'Limite sugerido na criação: '+c.attributeLimit+'.'}</p></section><section class="panel section-gap"><div class="panel-head"><h2>Pronto para o combate</h2>${btn('go-session','Abrir mesa →','ghost small')}</div><div class="stat-row"><div class="stat"><small>ATAQUE CORPO A CORPO</small><strong>${s.fa} + 1d</strong><small>F + H · ${esc(c.damageMelee)}</small></div><div class="stat"><small>ATAQUE À DISTÂNCIA</small><strong>${s.far} + 1d</strong><small>PdF + H · ${esc(c.damageRanged)}</small></div><div class="stat"><small>DEFESA</small><strong>${s.fd}${s.helpless?' (sem dado)':' + 1d'}</strong><small>A + H</small></div></div></section><section class="panel section-gap"><div class="panel-head"><h2>O que torna seu herói único</h2>${btn('go-powers','Explorar opções →','ghost small')}</div>${c.items.length?`<div class="actions">${c.items.slice(0,12).map(i=>`<span class="chip">${esc(i.name)}${i.quantity>1?' ×'+i.quantity:''}</span>`).join('')}</div>`:empty('Adicione vantagens, perícias, magias e kits ao seu personagem.','go-powers','Encontrar minha primeira vantagem')}</section></div><div><section class="panel"><div class="panel-head"><h2>Recursos</h2>${btn('rest','Restaurar','ghost small')}</div>${resources(c,s)}<p class="hint">${s.currentPV===0?'Sem PVs: consulte os testes de morte.':s.nearDeath?'Perto da morte: PVs até R, com máximo de 5.':'Acompanhe os recursos durante a sessão.'}</p></section><section class="panel section-gap"><div class="panel-head"><h2>Conferência da ficha</h2><span class="chip ${s.warnings.length?'orange':'green'}">${s.warnings.length||'✓'}</span></div>${validation(s)}<p class="hint">Requisitos narrativos e efeitos situacionais precisam da decisão do mestre.</p></section><section class="panel section-gap"><div class="eyebrow">CONTINUE SUA HISTÓRIA</div><h3>Um acervo inteiro ao seu lado.</h3><p style="font-size:12px">Consulte regras, criaturas e cenários sem sair da sua ficha.</p>${btn('go-library','Explorar biblioteca →','ghost small')}</section></div></div>`}
function character(c,s){return heading('Quem é seu herói?','Identidade, características e a história que conecta tudo.')+`<div class="grid cols2"><section class="panel"><h2>Identidade</h2><div class="field-grid">${field('Nome do personagem','name',c.name)}${field('Jogador','player',c.player)}${field('Conceito / ocupação','concept',c.concept)}${field('Campanha','campaign',c.campaign)}${field('Idade','age',c.age)}${select('Escala','scale',['Ningen','Sugoi','Kiodai','Kami'],c.scale)}</div><div class="divider"></div><div class="actions">${btn('portrait','Escolher retrato','small')}${c.portrait?btn('remove-portrait','Remover retrato','ghost small'):''}${btn('duplicate','Duplicar personagem','ghost small')}${btn('delete-character','Excluir personagem','danger ghost small')}</div><p class="hint">Retratos ficam dentro do arquivo compartilhado. PNG, JPG ou WebP, até 4 MB.</p></section><section class="panel"><h2>Características</h2>${attributes(c,s)}<div class="divider"></div><div class="field-grid">${select('Dano de Força','damageMelee',['Esmagamento','Corte','Perfuração','Fogo','Frio','Elétrico','Químico','Sônico','Energia'],c.damageMelee)}${select('Dano de Poder de Fogo','damageRanged',['Esmagamento','Corte','Perfuração','Fogo','Frio','Elétrico','Químico','Sônico','Energia'],c.damageRanged)}</div></section></div><div class="grid cols2 section-gap"><section class="panel">${area('Aparência e personalidade','appearance',c.appearance)}</section><section class="panel">${area('História, vínculos e objetivos','story',c.story)}</section></div><section class="panel section-gap">${area('Anotações livres','notes',c.notes)}</section>`}
function itemList(c,categories){const items=c.items.filter(i=>categories.includes(i.category));return items.length?`<div class="list">${items.map(i=>`<div class="list-item"><div><h3>${esc(i.name)} ${i.quantity>1?`<span class="chip">×${i.quantity}</span>`:''}</h3><small>${cats[i.category]} · ${i.category==='kit'?'custo por ordem dos kits':`${i.cost*i.quantity} ${i.currency||'pontos'}`} · ${esc(bookTitle(i.book))}${i.page?' · PDF p. '+i.page:''}</small>${choiceText(i)?`<p>${esc(choiceText(i))}</p>`:''}${i.notes?`<p>${esc(i.notes)}</p>`:''}${i.needsReview&&!i.confirmed?'<p class="warning-count">Conferência pendente</p>':''}</div><div class="actions">${['Arena','Ataque Especial'].includes(i.name)?btn('activate-item','Usar efeito','primary small',`data-id="${i.id}"`):''}${i.category==='magia'?btn('cast','Conjurar','primary small',`data-id="${i.id}"`):''}${btn('edit-item','Detalhes','small',`data-id="${i.id}"`)}${btn('remove-item','×','ghost danger',`data-id="${i.id}" aria-label="Remover ${esc(i.name)}"`)}</div></div>`).join('')}</div>`:empty('Sua seleção aparece aqui. Encontre uma opção no catálogo ou crie uma regra personalizada.','catalog','Abrir catálogo')}
function powers(c){return heading('Cada escolha conta.','Vantagens, limitações, raças e conhecimentos do personagem.',btn('custom','+ Opção personalizada','primary'))+`<div class="tabs">${btn('list','Na minha ficha',tab==='lista'?'active':'')}${btn('catalog','Catálogo dos livros',tab==='catalogo'?'active':'')}</div>${tab==='catalogo'?catalog():itemList(c,['vantagem','desvantagem','unica','pericia','especializacao','regra','criatura'])}<p class="footer-note">Vantagens únicas: os ajustes de características são visíveis nos detalhes. Opções situacionais e regras dos suplementos têm campos de ajuste próprios.</p>`}
function magic(c){return heading('Mais possibilidades.','Magias, kits e poderes especiais com suas referências.',btn('custom','+ Opção personalizada','primary'))+`<div class="tabs">${btn('list','Na minha ficha',tab==='lista'?'active':'')}${btn('catalog','Catálogo dos livros',tab==='catalogo'?'active':'')}</div>${tab==='catalogo'?catalog():itemList(c,['magia','kit','poder'])}<div class="panel section-gap"><h3>Como os custos funcionam</h3><p class="hint">Primeiro kit gratuito; segundo custa 1 ponto; terceiro custa 2, e assim por diante. O primeiro poder de cada kit é gratuito e os adicionais custam 1 ponto cada: registre-os como “Poder de kit”. Magias iniciais não consomem pontos de personagem; aprender uma nova magia custa normalmente 1 PE. Confira as exceções no livro.</p></div>`}
function catalog(){const notice=C.localAvailable?'':`<section class="panel section-gap"><h3>Configure seu acervo local</h3><p>O código público acompanha as regras e a ficha. Para pesquisar os livros, importe o acervo da sua distribuição com o procedimento do README. Você pode adicionar opções personalizadas enquanto isso.</p></section>`;const q=R.normalize(filter.query);const result=searchResult('catalog',filter),all=result.rows;const max=Math.ceil(result.total/30);return notice+`<div class="filters"><input id="catalog-search" aria-label="Pesquisar no catálogo" placeholder="Busque por nome, efeito ou requisito…" value="${esc(filter.query)}"><select id="catalog-category" aria-label="Categoria">${opts([['','Todas as categorias'],...Object.entries(cats)],filter.category)}</select><select id="catalog-book" aria-label="Livro de origem">${opts([['','Todos os livros'],...C.books.map(b=>[b.id,b.title])],filter.book)}</select></div><div class="panel-head"><span class="muted">${result.pending?'Preparando pesquisa…':result.error?'Pesquisa indisponível':result.total+' entradas encontradas'}</span><span class="chip">FONTE SEMPRE VISÍVEL</span></div><div class="catalog-grid">${all.map(e=>`<article class="catalog-card"><div class="actions"><span class="chip ${e.book==='3d&tManualbasico'?'green':''}">${cats[e.category]}</span><span class="chip">${e.costLabel?esc(e.costLabel):e.cost!=null?e.cost+' pontos':'Conferir custo'}</span></div><h3>${esc(e.name)}</h3>${basicGuide(e)?'<span class="chip green">Básico · custo conferido</span>':''}<p>${esc(basicGuide(e)?.summary||e.text)}</p><small>${esc(bookTitle(e.book))} · PDF p. ${e.page}</small><div class="actions">${btn('entry','Consultar','ghost small',`data-id="${e.id}"`)}${btn('add-entry','+ Adicionar','primary small',`data-id="${e.id}"`)+(e.category==='criatura'?btn('npc','Criar NPC','small',`data-id="${e.id}"`):'')}</div></article>`).join('')}</div>${!result.pending&&!result.error&&!all.length?empty('Nenhuma opção encontrada. Experimente outro livro ou pesquise na biblioteca.'):''}<div class="actions section-gap">${btn('catalog-prev','← Anterior','small',filter.page===0?'disabled':'')}<small>Página ${filter.page+1} de ${Math.max(1,max)}</small>${btn('catalog-next','Próxima →','small',filter.page>=max-1?'disabled':'')}</div><p class="footer-note">O catálogo foi extraído dos PDFs. Verifique o texto e a página original ao escolher variantes; custos variáveis, pré-requisitos e efeitos especiais são configurados ao adicionar.</p>`}
function inventory(c){return heading('Tudo para a jornada.','Equipamentos, tesouros e itens que acompanham o seu personagem.',btn('add-equipment','+ Adicionar item','primary'))+`<div class="grid cols3"><div class="panel">${field('Dinheiro / unidades da campanha','cash',c.cash,'number')}</div><div class="panel"><label>Peso registrado</label><div class="dice-result">${c.inventory.reduce((s,i)=>s+i.weight*i.quantity,0).toLocaleString('pt-BR')} kg</div></div><div class="panel"><label>Itens na mochila</label><div class="dice-result">${c.inventory.reduce((s,i)=>s+i.quantity,0)}</div></div></div><div class="section-gap">${c.inventory.length?`<div class="list">${c.inventory.map(i=>`<div class="list-item"><div><h3>${esc(i.name)} <span class="chip">×${i.quantity}</span> ${i.equipped?'<span class="chip green">Equipado</span>':''}</h3><small>${i.weight} kg / unidade</small><p>${esc(i.notes)}</p></div><div class="actions">${btn('edit-equipment','Editar','small',`data-id="${i.id}"`)}${btn('remove-equipment','Remover','danger ghost small',`data-id="${i.id}"`)}</div></div>`).join('')}</div>`:empty('A mochila ainda está vazia.','add-equipment','Adicionar equipamento')}</div><p class="footer-note">Equipamento comum não altera características automaticamente em 3D&T. Registre bônus de armas mágicas, mechas e outros itens especiais em Campanha e ajustes.</p>`}
function session(c,s){return heading('A aventura está acontecendo.','Recursos, rolagens, condições e evolução em um só lugar.',btn('rest','Restaurar PV e PM','primary'))+`<div class="grid cols2"><section class="panel"><h2>Recursos de sessão</h2>${resources(c,s)}<div class="divider"></div><h3>Aplicar dano ou recuperar</h3><div class="actions"><input id="resource-amount" class="inline-num" type="number" value="1" min="0" aria-label="Quantidade de pontos">${btn('damage','Sofrer dano','small')}${btn('heal','Recuperar PV','small')}${btn('spend-pm','Gastar PM','small')}${btn('heal-pm','Recuperar PM','small')}</div><div class="divider"></div><h3>Condições</h3><div class="actions">${['Perto da morte','Inconsciente','Paralisado','Indefeso','Invisível','Voando','Envenenado','Concentrando'].map(x=>btn('condition',esc(x),c.conditions.includes(x)?'primary small':'small',`data-condition="${x}"`)).join('')}</div><p class="hint">Indefeso, Paralisado e Inconsciente alteram a defesa e impedem esquiva. Outros marcadores dependem dos efeitos registrados pelo mestre.</p></section><section class="panel"><h2>Rolagem de dados</h2><div class="field-grid"><div><label for="roll-type">Ação ou teste</label><select id="roll-type">${opts([['melee','Ataque corpo a corpo'],['ranged','Ataque à distância'],['defense','Defesa'],['initiative','Iniciativa'],['dodge','Esquiva'],['d6','1d6 livre'],...R.attrs.map(k=>[k,'Teste de '+names[k]])],'melee')}</select></div><div><label for="roll-mod">Modificador situacional</label><input id="roll-mod" data-preserve="true" type="number" value="0"></div></div><div class="actions section-gap">${btn('roll','⚄ Rolar dado','primary')}${btn('death','Teste de morte','ghost small')}</div><div id="last-roll" class="section-gap" aria-live="polite"></div><p class="hint">Crítico (6): dobra F, PdF ou A na rolagem correspondente. Testes de característica sempre falham com 6. O contexto de combate aplica Armadura Extra, vulnerabilidade e testes de escala quando selecionados.</p><div class="divider"></div><h3>Teste de perícia</h3><div class="field-grid"><div><label for="skill-training">Treinamento</label><select id="skill-training">${opts(['Perícia completa','Especialização aplicável','Sem treinamento'],'Perícia completa')}</select></div><div><label for="skill-difficulty">Dificuldade</label><select id="skill-difficulty">${opts(['Fácil','Média','Difícil'],'Média')}</select></div></div>${btn('skill-roll','Testar perícia','small','style="margin-top:12px"')}</section></div><div class="grid cols2 section-gap"><section class="panel"><h2>Experiência</h2><div class="dice-result">${c.xp} <small>PE disponíveis</small></div><p class="hint">Pontos convertidos: ${c.earnedPoints}. A conversão de 10 PE libera 1 ponto para compras na ficha.</p><div class="actions section-gap"><input id="xp-amount" class="inline-num" type="number" min="1" value="1" aria-label="Quantidade de PE">${btn('gain-xp','Receber PE','small')}${btn('spend-xp','Gastar PE','small')}${btn('convert-xp','10 PE → 1 ponto','primary small')}</div><div class="divider"></div><h3>Diário de aventuras</h3><textarea id="journal-text" placeholder="O que aconteceu nesta sessão?" aria-label="Nova anotação do diário"></textarea>${btn('journal','Registrar sessão','small','style="margin-top:10px"')}<div class="history">${c.journal.slice().reverse().map(j=>`<div><small>${esc(j.date)}</small>${esc(j.text)}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Registro da mesa</h2>${btn('clear-history','Limpar','ghost small')}</div><div class="history">${c.history.slice().reverse().map(j=>`<div><small>${esc(j.date)}</small>${esc(j.text)}</div>`).join('')||'<p>Nenhuma rolagem ainda. Sua aventura começa com um dado.</p>'}</div></section></div>`}
function library(){const notice=C.localAvailable?'':`<section class="panel section-gap"><h3>Configure seu acervo local</h3><p>Os PDFs e o catálogo integral não acompanham o repositório público. Consulte o README para importar da sua cópia local.</p></section>`;const q=R.normalize(lib.query);const result=q?searchResult('library',lib):{rows:[],total:0},matches=result.rows;return heading('Conhecimento é poder.','Consulte as fontes configuradas localmente, com acesso à página original.')+notice+`<div class="filters"><input id="library-search" placeholder="Pesquisar regras, criaturas, locais e magias…" aria-label="Pesquisar na biblioteca" value="${esc(lib.query)}"><select id="library-book" aria-label="Filtrar livro">${opts([['','Todos os livros'],...C.books.map(b=>[b.id,b.title])],lib.book)}</select></div>${q?`<section class="panel"><div class="panel-head"><h2>${result.pending?'Preparando pesquisa…':result.error?'Pesquisa indisponível':result.total+' páginas encontradas'}</h2><small>Mostrando até 30 por vez</small></div>${matches.map(p=>{const index=120;return `<article class="result"><div class="panel-head"><h3>${esc(bookTitle(p.book))}</h3><span class="chip">PDF P. ${p.page}</span></div><p>…${esc(p.text.slice(Math.max(0,index-120),index+350))}…</p><div class="actions">${btn('read-page','Ler texto','small',`data-book="${p.book}" data-page="${p.page}"`)}${btn('source','Abrir PDF','ghost small',`data-book="${p.book}" data-page="${p.page}"`)}</div></article>`}).join('')}<div class="actions section-gap">${btn('lib-prev','← Anterior','small',lib.page===0?'disabled':'')}<small>Página ${lib.page+1}</small>${btn('lib-next','Próxima →','small',(lib.page+1)*30>=result.total?'disabled':'')}</div></section>`:`<div class="book-grid">${C.books.filter(b=>!lib.book||lib.book===b.id).map((b,i)=>`<article class="book"><div class="eyebrow">ACERVO / ${String(i+1).padStart(2,'0')}</div><h3>${esc(b.title)}</h3><small>${b.pages} páginas · ${C.localAvailable?'acervo configurado':'fonte prevista'}</small><div class="actions">${btn('source','Abrir livro →','small',`data-book="${b.id}" data-page="1"`)}${btn('book-catalog','Catálogo','ghost small',`data-book="${b.id}"`)}</div></article>`).join('')}</div>`}<p class="footer-note">“PDF p.” indica a página do arquivo, que pode diferir da numeração impressa. As extrações de texto podem conter falhas de leitura; o PDF original é a referência final. 3D&T e os livros pertencem aos respectivos autores e editoras. Este é um projeto pessoal independente.</p>`}
function settings(c,s){return heading('A sua mesa, as suas regras.','Defina a campanha e registre os ajustes aprovados pelo mestre.')+`<div class="grid cols2"><section class="panel"><h2>Pontuação e limites</h2><label for="preset">Perfil inicial</label><select id="preset">${opts([['','Personalizado'],['5','Novato · 5 pontos / até −3'],['7','Lutador · 7 pontos / até −4'],['10','Campeão · 10 pontos / até −5'],['12','Lenda · 12 pontos / até −6']],String(c.budget))}</select><div class="field-grid section-gap">${field('Pontos iniciais','budget',c.budget,'number')}${field('Limite de desvantagens (valor positivo)','limitDisadvantages',c.limitDisadvantages,'number')}${field('Pontos extras / evolução','earnedPoints',c.earnedPoints,'number')}${field('PE disponíveis','xp',c.xp,'number')}${select('Fase do personagem','phase',[['criacao','Criação'],['evolucao','Em evolução']],c.phase)}</div><p class="hint">Os ajustes abaixo afetam os resultados, mas não custam pontos. Registre a origem nas anotações. A mesa de jogo converte o dano entre escalas. Os valores da ficha são mostrados na própria escala.</p></section><section class="panel"><h2>Ajustes permanentes e especiais</h2><div class="field-grid">${Object.keys(c.modifiers).map(k=>field(effectNames[k]+' · bônus / redutor','modifiers.'+k,c.modifiers[k],'number')).join('')}</div></section></div><div class="grid cols2 section-gap"><section class="panel"><h2>Resumo do orçamento</h2><div class="list"><div class="list-item">Características <strong>${s.base}</strong></div><div class="list-item">Vantagens, perícias e outros <strong>${s.itemCost}</strong></div><div class="list-item">Aquisição de kits <strong>${s.kitCost}</strong></div><div class="list-item">Disponíveis <strong>${s.remaining}</strong></div></div><div class="section-gap">${validation(s)}</div></section><section class="panel"><h2>Seus dados, sempre com você</h2><p>Exporte uma ficha para compartilhar ou um backup com todos os personagens. Ao importar, as fichas entram como novas cópias.</p><div class="actions">${btn('backup','Exportar backup completo','primary')}${btn('import','Importar fichas','small')}</div><div class="divider"></div><h3>Cobertura das regras</h3><p class="hint">Cálculo de características, pontos, PV/PM, extras, combate básico, críticos, testes e aquisição de kits. A biblioteca usa os livros e o catálogo importados localmente. O repositório público não distribui os textos integrais. O catálogo é uma extração assistida: cada opção pode ter custo, quantidade, requisitos, bônus e notas ajustados. Habilidades condicionais, escolhas internas, poderes de kit e exceções de suplementos são resolvidos com o mestre e registrados na ficha.</p></section></div>`}
function openModal(title,content,actions=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2></div>${btn('close','×','ghost','aria-label="Fechar janela"')}</div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!m.open)m.showModal()}
function closeModal(){$('#modal').close()}
function log(text){ch().history.push({date:new Date().toLocaleString('pt-BR'),text});ch().history=ch().history.slice(-100);save()}
function entryDetails(e){openModal(e.name,`<p>${esc(bookTitle(e.book))} · PDF p. ${e.page}</p><div class="entry-text">${esc(e.text)}</div>`,btn('source','Abrir página original','small',`data-book="${e.book}" data-page="${e.page}"`)+btn('add-entry','Adicionar à ficha','primary',`data-id="${e.id}"`))}
const effectDefaults={'Elfo':{H:1},'Elfo Negro':{H:1},'Halfling':{H:1,PdF:1},'Anfíbio':{R:1},'Centauro':{F:1},'Minotauro':{F:2,R:1},'Ogre':{F:3,R:3},'Troglodita':{F:1,A:1}};
function itemEditor(entry=null,existing=null){
 const i=existing?structuredClone(existing):{id:R.uid(),name:entry?.name||'',category:entry?.category||(view==='magias'?'magia':'vantagem'),cost:entry?.cost??0,quantity:1,currency:entry?.currency||'pontos',text:entry?.text||'',notes:'',book:entry?.book||'',page:entry?.page||1,needsReview:true,confirmed:false,effects:entry?.book==='3d&tManualbasico'?structuredClone(effectDefaults[entry.name]||{}):{},requirements:Object.fromEntries([...(entry?.text?.match(/Exigências:\s*([^.]*)/)?.[1]||'').matchAll(/\b(PdF|F|H|R|A)(\d+)\b/g)].map(m=>[m[1],Number(m[2])]))};
 window.editingItem={item:i,existing:!!existing};
 const ef=(label,id,val,type='text')=>`<div><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(val)}" ${type==='number'?`step="${id.startsWith('effect-')||id==='item-cost'?'any':'1'}"`:''}></div>`;
 openModal(existing?'Editar opção':'Adicionar à ficha',`<div class="field-grid">${ef('Nome','item-name',i.name)}<div><label for="item-category">Categoria</label><select id="item-category">${opts(Object.entries(cats),i.category)}</select></div>${ef('Custo por unidade (negativo para desvantagem)','item-cost',i.cost,'number')}${ef('Quantidade / níveis','item-quantity',i.quantity,'number')}<div><label for="item-currency">Moeda do custo</label><select id="item-currency">${opts(['pontos','PE'],i.currency)}</select></div><div><label>Origem</label><small>${esc(bookTitle(i.book))}${i.book?' · PDF p. '+i.page:''}</small></div></div>${entry?.costLabel?`<p class="hint">Custo indicado na fonte: ${esc(entry.costLabel)}.</p>`:''}<p class="hint">Especializações: registre até três escolhas em uma única opção de 1 ponto. Kits têm custo progressivo automático. Magias iniciais: 0 pontos. Para uma magia aprendida em jogo, escolha 1 PE. Ao adicionar uma opção em PE, o saldo é debitado; editar ou remover depois não restitui PE automaticamente.</p><div class="divider"></div><label for="item-notes">Escolhas, variantes, poderes recebidos e observações</label><textarea id="item-notes" placeholder="Ex.: elemento fogo, código dos heróis, poder inicial do kit…">${esc(i.notes)}</textarea><details class="section-gap" ${Object.keys(i.effects||{}).length?'open':''}><summary>Bônus permanentes (aplicados automaticamente)</summary><div class="field-grid section-gap">${R.effectKeys.map(k=>ef(effectNames[k]||k.toUpperCase(),'effect-'+k,i.effects?.[k]||0,'number')).join('')}</div><p class="hint">Somente bônus permanentes. Pontos de Vida/Magia Extras já são calculados pelo nome e pela quantidade. Não repita o bônus aqui.</p></details><details class="section-gap"><summary>Requisitos mínimos de características</summary><div class="field-grid section-gap">${R.attrs.map(k=>ef(names[k],'require-'+k,i.requirements?.[k]||0,'number')).join('')}</div></details>${i.text?`<details class="section-gap"><summary>Consultar texto da fonte</summary><div class="entry-text section-gap">${esc(i.text)}</div>${btn('source','Abrir PDF original','small',`data-book="${esc(i.book)}" data-page="${i.page}" style="margin-top:10px"`)}</details>`:`<div class="section-gap"><label for="item-text">Descrição da regra</label><textarea id="item-text"></textarea></div>`}<label class="toggle-label section-gap"><input id="item-confirm" type="checkbox" ${i.confirmed?'checked':''}>Conferi o custo, os requisitos e as escolhas desta opção.</label>`,btn('close','Cancelar','ghost')+btn('save-item',existing?'Salvar alterações':'Adicionar à ficha','primary'));
}
function equipmentEditor(item){window.editingEquipment=item||null;openModal(item?'Editar equipamento':'Novo equipamento',`<div class="field-grid"><div><label for="eq-name">Nome</label><input id="eq-name" value="${esc(item?.name||'')}"></div><div><label for="eq-qty">Quantidade</label><input id="eq-qty" type="number" min="0" value="${item?.quantity??1}"></div><div><label for="eq-weight">Peso unitário (kg)</label><input id="eq-weight" type="number" min="0" step="0.1" value="${item?.weight??0}"></div><label class="toggle-label"><input id="eq-equipped" type="checkbox" ${item?.equipped?'checked':''}>Equipado</label></div><div class="section-gap"><label for="eq-notes">Descrição, cargas, bônus e efeitos</label><textarea id="eq-notes">${esc(item?.notes||'')}</textarea></div>`,btn('close','Cancelar','ghost')+btn('save-equipment','Salvar item','primary'))}
function download(content,name,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportData(all=false){await flushSave();const data=R.pack(all?state.characters:[ch()]),name=all?'Forja-Backup':ch().name;const result=window.desktop?await desktop.export(data,name):(download(JSON.stringify(data,null,2),name+'.3det.json'),true);if(result)toast(all?'Backup completo exportado.':'Ficha exportada. Envie o arquivo para outra pessoa importar.')}
async function importData(raw){const added=R.validateImport(raw);for(const c of added)if(state.characters.some(x=>x.name===c.name))c.name+=' (importado)';state.characters.push(...added);state.selected=added[0].id;storageBlocked=false;save();render();toast(`${added.length} ficha(s) importada(s) como novas cópias.`)}
function confirmAction(title,text,action){openModal(title,`<p>${esc(text)}</p>`,btn('close','Cancelar','ghost')+btn(action,'Confirmar','danger'))}
function printHTML(c){const s=R.calculate(c);return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:"><title>Ficha de ${esc(c.name)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font:10pt 'Segoe UI',Arial,sans-serif;color:#23332d;margin:0}h1{font-size:27pt;letter-spacing:-1px;margin:8px 0}h2{font-size:13pt;border-bottom:2px solid #c6d8c4;padding-bottom:7px;margin-top:23px;break-after:avoid}h3{font-size:11pt;margin:12px 0 5px}.top{border-bottom:3px solid #345e40;padding-bottom:14px;display:flex;gap:20px;align-items:center}.top img{width:75px;height:90px;object-fit:cover;border-radius:8px}.kicker{font-size:9pt;letter-spacing:2px;color:#4f6e57}p{line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}small{font-size:8pt;color:#607168}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin:20px 0}.attr{border:1px solid #bacbbd;border-radius:7px;padding:12px;text-align:center}.attr strong{font-size:24pt;display:block;margin-top:4px;overflow-wrap:anywhere}.attr,.stat{min-width:0;overflow-wrap:anywhere}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.stat{background:#eff4ec;padding:11px;border-radius:6px}.item{break-inside:avoid;margin-bottom:12px}.muted{color:#607168}.warning{background:#fff1de;padding:10px}.footer{margin-top:25px;font-size:8pt;color:#607168;border-top:1px solid #c6d8c4;padding-top:10px}table{border-collapse:collapse;width:100%;font-size:9pt}td,th{padding:7px;text-align:left;border-bottom:1px solid #d9e2d7}tr{break-inside:avoid}</style></head><body><div class="top">${c.portrait?`<img alt="Retrato" src="${c.portrait}">`:''}<div><div class="kicker">FORJA / 3D&T ALPHA</div><h1>${esc(c.name)}</h1><p>${esc(c.concept)}</p><small>Jogador: ${esc(c.player||'—')} · Campanha: ${esc(c.campaign||'—')} · Escala: ${esc(c.scale)}</small></div></div><div class="grid">${R.attrs.map(k=>`<div class="attr">${names[k]}<strong>${s.attrs[k]}</strong></div>`).join('')}</div><div class="stats"><div class="stat"><b>PV ${s.currentPV} / ${s.pv}</b><p>PM ${s.currentPM} / ${s.pm}</p></div><div class="stat"><b>FA ${s.fa} + 1d</b><p>FA à distância ${s.far} + 1d<br>FD ${s.fd}${s.helpless?' (sem dado)':' + 1d'}</p></div><div class="stat"><b>${s.spent} / ${s.available} pontos</b><p>${c.xp} PE · ${s.remaining} pontos livres</p></div></div><p><small>Dano de Força: ${esc(c.damageMelee)} · Dano de PdF: ${esc(c.damageRanged)}<br>Condições: ${esc(c.conditions.join(', ')||'Nenhuma registrada')}</small></p>${s.warnings.length?`<p class="warning">Conferência: ${esc(s.warnings.join(' '))}</p>`:''}${Object.entries(cats).map(([cat,label])=>{const items=c.items.filter(i=>i.category===cat);return items.length?`<h2>${label}</h2>${items.map(i=>`<div class="item"><h3>${esc(i.name)}${i.quantity>1?' ×'+i.quantity:''} <small>(${i.category==='kit'?'custo progressivo':i.cost*i.quantity+' '+i.currency})</small></h3>${choiceText(i)?`<p>${esc(choiceText(i))}</p>`:''}<p>${esc(i.notes)}</p><small>${esc(bookTitle(i.book))}${i.book?' · PDF p. '+i.page:''}</small>${i.text?`<p>${esc(i.text)}</p>`:''}</div>`).join('')}`:''}).join('')}${c.inventory.length?`<h2>Equipamentos</h2><table><thead><tr><th>Item</th><th>Qtd.</th><th>Peso un.</th><th>Notas</th></tr></thead><tbody>${c.inventory.map(i=>`<tr><td>${esc(i.name)}${i.equipped?' (equipado)':''}</td><td>${i.quantity}</td><td>${i.weight} kg</td><td>${esc(i.notes)}</td></tr>`).join('')}</tbody></table>`:''}<p>Dinheiro: ${c.cash.toLocaleString('pt-BR')}</p>${[['Aparência e personalidade',c.appearance],['História',c.story],['Anotações',c.notes]].map(([title,text])=>text?`<h2>${title}</h2><p>${esc(text)}</p>`:'').join('')}${c.journal.length?`<h2>Diário de aventuras</h2>${c.journal.map(j=>`<div class="item"><small>${esc(j.date)}</small><p>${esc(j.text)}</p></div>`).join('')}`:''}<div class="footer">Forja 3D&T Alpha · Ficha pessoal · ${new Date().toLocaleDateString('pt-BR')}<br>Projeto independente. Regras e livros de seus respectivos autores. Os valores incluem ajustes registrados na ficha.</div></body></html>`}
const actions={
 close:closeModal,
 new:()=>openModal('Uma nova história',`<p>Escolha um nome e um ponto de partida. Você pode mudar tudo depois.</p><div class="field-grid"><div><label for="new-name">Nome</label><input id="new-name" placeholder="Nome do seu personagem" autofocus></div><div><label for="new-preset">Pontuação inicial</label><select id="new-preset">${opts([['5','Novato · 5 pontos'],['7','Lutador · 7 pontos'],['10','Campeão · 10 pontos'],['12','Lenda · 12 pontos']],'10')}</select></div></div>`,btn('close','Cancelar','ghost')+btn('create-character','Criar personagem','primary')),
 'create-character':()=>{const c=R.create($('#new-name').value.trim()||'Novo personagem');c.budget=Number($('#new-preset').value);c.limitDisadvantages=({5:3,7:4,10:5,12:6})[c.budget];state.characters.push(c);state.selected=c.id;view='personagem';closeModal();save();render()},
 identity:()=>{view='personagem';render()},'go-session':()=>{view='sessao';render()},'go-powers':()=>{view='poderes';tab='catalogo';filter.category='vantagem';render()},'go-library':()=>{view='biblioteca';render()},
 attr:el=>{const c=ch(),k=el.dataset.key;c.attrs[k]=R.number(c.attrs[k]+Number(el.dataset.delta),names[k],0,R.MAX,true);save();render()},
 resource:el=>{const c=ch(),s=R.calculate(c),k=el.dataset.key;c['current'+k]=R.clamp(s['current'+k]+Number(el.dataset.delta),0,s[k.toLowerCase()]);save();render()},
 rest:()=>{const c=ch();c.currentPV=null;c.currentPM=null;log('PV e PM restaurados ao máximo por comando do jogador.');render()},
 duplicate:()=>{const copy=R.validateImport(R.pack([ch()]))[0];copy.name+=' (cópia)';state.characters.push(copy);state.selected=copy.id;save();render();toast('Personagem duplicado.')},
 'delete-character':()=>confirmAction('Excluir personagem?',`Excluir “${ch().name}” deste dispositivo? Exporte a ficha primeiro se quiser guardar uma cópia.`,'confirm-delete-character'),
 'confirm-delete-character':()=>{state.characters=state.characters.filter(c=>c.id!==ch().id);if(!state.characters.length)state.characters=[R.create()];state.selected=state.characters[0].id;closeModal();save();render()},
 portrait:()=>$('#portrait-file').click(),'remove-portrait':()=>{ch().portrait='';save();render()},
 list:()=>{tab='lista';render()},catalog:()=>{tab='catalogo';filter.category=view==='magias'?'magia':'vantagem';filter.page=0;render()},
 'catalog-prev':()=>{filter.page--;render()},'catalog-next':()=>{filter.page++;render()},
 entry:el=>entryDetails((C.entries.find(e=>e.id===el.dataset.id)|| (window.modalEntry?.id===el.dataset.id?window.modalEntry:null))),
 'add-entry':el=>itemEditor((C.entries.find(e=>e.id===el.dataset.id)|| (window.modalEntry?.id===el.dataset.id?window.modalEntry:null))),custom:()=>itemEditor(),
 'edit-item':el=>itemEditor(null,ch().items.find(i=>i.id===el.dataset.id)),
 npc:el=>{const e=(C.entries.find(e=>e.id===el.dataset.id)|| (window.modalEntry?.id===el.dataset.id?window.modalEntry:null)),c=R.create(e.name);const found=[...e.text.matchAll(/\b(PdF|F|H|R|A)\s*(\d+)\b/g)];for(const k of R.attrs){const m=found.find(m=>m[1]===k);if(m)c.attrs[k]=Number(m[2])}c.phase='evolucao';c.budget=R.attrs.reduce((sum,k)=>sum+c.attrs[k],0);c.concept='NPC · '+bookTitle(e.book);c.items=[{id:R.uid(),name:e.name,category:'criatura',cost:0,quantity:1,currency:'pontos',text:e.text,book:e.book,page:e.page,needsReview:true,confirmed:false,notes:'Características sugeridas pela extração do texto. Confira a ficha original antes de usar.',effects:{},requirements:{}}];state.characters.push(c);state.selected=c.id;view='personagem';save();render();toast('NPC criado. Confira características e poderes com a ficha original.');},
 'save-item':()=>{let {item,existing}=window.editingItem;let i=structuredClone(item);i.name=$('#item-name').value.trim();if(!i.name)throw Error('Dê um nome à opção.');i.category=$('#item-category').value;i.cost=R.number($('#item-cost').value,'Custo');i.quantity=R.number($('#item-quantity').value,'Quantidade',1,R.MAX,true);i.currency=$('#item-currency').value;i.notes=$('#item-notes').value;i.confirmed=$('#item-confirm').checked;i.needsReview=true;i.effects=Object.fromEntries(R.effectKeys.map(k=>[k,R.number($('#effect-'+k).value,'Efeito '+k)]));i.requirements=Object.fromEntries(R.attrs.map(k=>[k,R.number($('#require-'+k).value,'Requisito '+k,0,R.MAX,true)]));if($('#item-text'))i.text=$('#item-text').value;if(i.category==='desvantagem'&&i.cost>0)throw Error('O custo de uma desvantagem deve ser zero ou negativo.');if(i.currency==='PE'&&i.cost<0)throw Error('Custos em PE não podem ser negativos.');if(i.category==='kit')i.quantity=1;const candidate=structuredClone(ch());if(!existing&&i.currency==='PE'){const cost=R.number(i.cost*i.quantity,'Custo total');if(candidate.xp<cost)throw Error('PE insuficientes para esta aquisição.');candidate.xp-=cost;candidate.history.push({date:new Date().toLocaleString('pt-BR'),text:`Aquisição de ${i.name}: ${cost} PE gastos.`});candidate.history=candidate.history.slice(-100)}if(existing)candidate.items[candidate.items.findIndex(x=>x.id===i.id)]=i;else candidate.items.push(i);R.calculate(candidate);Object.assign(ch(),candidate);save();closeModal();render();toast('Opção salva na ficha.')},
 'remove-item':el=>{window.removingItem=el.dataset.id;confirmAction('Remover opção?','O custo em pontos será recalculado. PE gastos anteriormente não são restituídos automaticamente.','confirm-remove-item')},
 'confirm-remove-item':()=>{ch().items=ch().items.filter(i=>i.id!==window.removingItem);closeModal();save();render()},
 'add-equipment':()=>equipmentEditor(), 'edit-equipment':el=>equipmentEditor(ch().inventory.find(i=>i.id===el.dataset.id)),
 'save-equipment':()=>{let name=$('#eq-name').value.trim();if(!name)throw Error('Informe o nome do equipamento.');let i={id:window.editingEquipment?.id||R.uid(),name,quantity:R.number($('#eq-qty').value,'Quantidade',0,R.MAX,true),weight:R.number($('#eq-weight').value,'Peso',0),equipped:$('#eq-equipped').checked,notes:$('#eq-notes').value};let index=ch().inventory.findIndex(x=>x.id===i.id);if(index<0)ch().inventory.push(i);else ch().inventory[index]=i;closeModal();save();render()},
 'remove-equipment':el=>{window.removingEquipment=el.dataset.id;confirmAction('Remover equipamento?','Este item será retirado da mochila.','confirm-remove-equipment')},
 'confirm-remove-equipment':()=>{ch().inventory=ch().inventory.filter(i=>i.id!==window.removingEquipment);closeModal();save();render()},
 condition:el=>{const x=el.dataset.condition,c=ch();c.conditions=c.conditions.includes(x)?c.conditions.filter(a=>a!==x):[...c.conditions,x];save();render()},
 roll:()=>{const result=R.roll(ch(),$('#roll-type').value,$('#roll-mod').value);const message=`${result.label}: dado ${result.die}${result.target!=null?` / alvo ${result.target} — ${result.success?'sucesso':'falha'}`:` → total ${result.total}${result.critical?' · CRÍTICO':''}`}`;log(message);render();$('#last-roll').innerHTML=`<div class="dice-result">${result.target!=null?(result.success?'Sucesso':'Falha'):result.total}</div><p>${esc(result.explanation||message)}</p>`},
 death:()=>{const d=R.die(),text=R.deathResult(d);log(`Teste de morte: ${d} — ${text}`);render();openModal('Teste de morte',`<div class="dice-result">${d}</div><p>${text}</p><p class="hint">Consulte os detalhes e modificadores no manual básico, PDF p. 27. O mestre determina a aplicação.</p>`,btn('source','Consultar regra','small','data-book="3d&tManualbasico" data-page="27"'))},
 'skill-roll':()=>{const trained=$('#skill-training').value!=='Sem treinamento',difficulty=$('#skill-difficulty').value;if(trained&&difficulty==='Fácil'){log('Teste de perícia fácil com treinamento: sucesso automático.');render();toast('Sucesso automático.');return}if(!trained&&difficulty==='Difícil'){log('Teste de perícia difícil sem treinamento: impossível.');render();toast('Tarefa impossível sem treinamento.');return}const mod=difficulty==='Fácil'?-1:difficulty==='Média'?(trained?1:-3):-2;const r=R.skillTest(ch(),trained,difficulty);const text=`Perícia (${difficulty.toLowerCase()}, ${trained?'treinado':'sem treinamento'}): dado ${r.die}, H${mod>=0?'+':''}${mod} = ${r.target} — ${r.success?'sucesso':'falha'}.`;log(text);render();toast(text)},
 cast:el=>{const i=ch().items.find(i=>i.id===el.dataset.id);window.casting=i;const m=i.text.match(/Custo:\s*(\d+)\s*PM/i);openModal('Conjurar '+i.name,`<div class="entry-text">${esc(i.text)}</div><div class="section-gap"><label for="cast-cost">Custo total em PM (inclua reduções e opções)</label><input id="cast-cost" type="number" min="0" value="${m?m[1]:1}"></div><p class="hint">Confirme escola, exigências, alcance e manutenção no texto. A conjuração debita apenas o custo informado.</p>`,btn('close','Cancelar','ghost')+btn('confirm-cast','Conjurar e gastar PM','primary'))},
 'confirm-cast':()=>{const amount=R.number($('#cast-cost').value,'Custo em PM',0),s=R.calculate(ch());if(s.currentPM<amount)throw Error('PM insuficientes.');ch().currentPM=s.currentPM-amount;log(`Conjurou ${window.casting.name}: ${amount} PM.`);closeModal();render()},
 'gain-xp':()=>{const n=R.number($('#xp-amount').value,'Experiência',1,R.MAX,true);ch().xp=R.number(ch().xp+n,'Experiência',0);log(`Recebeu ${n} PE.`);render()},
 'spend-xp':()=>{const n=R.number($('#xp-amount').value,'Experiência',1,R.MAX,true);if(ch().xp<n)throw Error('PE insuficientes.');ch().xp-=n;log(`Gastou ${n} PE.`);render()},
 'convert-xp':()=>{if(ch().xp<10)throw Error('Você precisa de 10 PE.');ch().xp-=10;ch().earnedPoints++;ch().phase='evolucao';log('Converteu 10 PE em 1 ponto de personagem.');render()},
 journal:()=>{const text=$('#journal-text').value.trim();if(!text)return;ch().journal.push({date:new Date().toLocaleString('pt-BR'),text});save();render()},
 'clear-history':()=>confirmAction('Limpar registro?','O registro de rolagens será apagado. As anotações do diário serão preservadas.','confirm-clear-history'),
 'confirm-clear-history':()=>{ch().history=[];closeModal();save();render()},
 'read-page':async el=>{const p=await workerRequest({kind:'page',book:el.dataset.book,page:Number(el.dataset.page)});openModal(bookTitle(p.book)+' · PDF p. '+p.page,`<div class="page-text">${esc(p.text)}</div>`,btn('source','Abrir PDF original','primary',`data-book="${p.book}" data-page="${p.page}"`))},
 source:async el=>{const b=C.books.find(b=>b.id===el.dataset.book);if(!b)throw Error('Esta opção não tem PDF associado.');if(window.desktop)await desktop.source(b.file,Number(el.dataset.page));else window.open('livros/'+encodeURIComponent(b.file)+'#page='+el.dataset.page,'_blank','noopener')},
 'book-catalog':el=>{view='poderes';tab='catalogo';filter.book=el.dataset.book;filter.category='';filter.query='';filter.page=0;render()},
 'lib-prev':()=>{lib.page--;render()},'lib-next':()=>{lib.page++;render()},
 export:()=>exportData(),backup:()=>exportData(true),import:async()=>{if(window.desktop){const raw=await desktop.import();if(raw)await importData(raw)}else $('#import-file').click()},
 pdf:async()=>{const html=printHTML(ch());if(window.desktop){const result=await desktop.pdf(html);if(result)toast('PDF salvo com sucesso.')}else{const w=window.open('','_blank');if(!w)throw Error('Permita a janela de impressão no navegador.');w.document.write(html);w.document.close();setTimeout(()=>w.print(),300)}}
};
for(const [action,k,sign] of [['damage','PV',-1],['heal','PV',1],['spend-pm','PM',-1],['heal-pm','PM',1]])actions[action]=()=>{const s=R.calculate(ch()),amount=R.number($('#resource-amount').value,'Quantidade',0);if(k==='PM'&&sign<0&&amount>s.currentPM)throw Error('PM insuficientes.');ch()['current'+k]=R.clamp(s['current'+k]+sign*amount,0,s[k.toLowerCase()]);if(action==='damage'&&amount>0)ch().conditions=ch().conditions.filter(x=>x!=='Paralisado');log(`${sign>0?'Recuperou':'Perdeu'} ${amount} ${k}.`);render()};
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.view){view=b.dataset.view;tab='lista';render();window.scrollTo(0,0)}else if(b.dataset.character){state.selected=b.dataset.character;save();render()}else if(actions[b.dataset.action])await actions[b.dataset.action](b)}catch(e){toast(e.message||'Não foi possível concluir a ação.')}});
let searchTimer;
function setField(el){const keys=el.dataset.field.split('.');let target=ch();for(const k of keys.slice(0,-1))target=target[k];const key=keys.at(-1),old=target[key];let value=el.value;
 if(el.type==='number'){if(value===''||!el.validity.valid)throw Error('Informe um número válido. O valor anterior foi preservado.');value=R.number(value,el.labels?.[0]?.textContent||key,['budget','earnedPoints','xp','limitDisadvantages','cash','attributeLimit','opponentH'].includes(key)?0:-R.MAX,R.MAX,['attributeLimit','opponentH'].includes(key));}
 if(['invulnerable','scaleTests'].includes(key))value=value==='true';
 target[key]=value;try{R.calculate(ch())}catch(e){target[key]=old;throw e}el.setCustomValidity('');save(keys[0]);}
 document.addEventListener('input',event=>{const el=event.target;if(el.dataset.field){el.setCustomValidity('');try{setField(el)}catch(e){el.setCustomValidity(e.message)}}
 if(['catalog-search','library-search'].includes(el.id)){if(el.id==='catalog-search'){filter.query=el.value;filter.page=0}else{lib.query=el.value;lib.page=0}clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if((el.id==='catalog-search'&&['poderes','magias'].includes(view)&&tab==='catalogo')||(el.id==='library-search'&&view==='biblioteca'))render()},120)}});
 document.addEventListener('change',event=>{const el=event.target;try{
 if(el.dataset.attr){const value=R.number(el.value,names[el.dataset.attr],0,R.MAX,true),old=ch().attrs[el.dataset.attr];ch().attrs[el.dataset.attr]=value;try{R.calculate(ch())}catch(e){ch().attrs[el.dataset.attr]=old;throw e}save('attrs');render()}
 else if(el.dataset.resource){const k=el.dataset.resource;ch()['current'+k]=R.number(el.value,k,0,R.calculate(ch())[k.toLowerCase()]);save('current'+k);render()}
 else if(el.id==='catalog-category'){filter.category=el.value;filter.page=0;render()}
 else if(el.id==='catalog-book'){filter.book=el.value;filter.page=0;render()}
 else if(el.id==='library-book'){lib.book=el.value;lib.page=0;render()}
 else if(el.id==='preset'&&el.value){ch().budget=Number(el.value);ch().limitDisadvantages=({5:3,7:4,10:5,12:6})[el.value];save();render()}
 else if(el.dataset.field){el.setCustomValidity('');setField(el);if(el.tagName==='SELECT')render()}
 }catch(e){el.setCustomValidity(e.message);toast(e.message)}});
 $('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(f){if(f.size>100*1024*1024)throw Error('Arquivo muito grande.');await importData(JSON.parse(await f.text()))}}catch(e){toast(e.message)}e.target.value=''});
$('#portrait-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>4*1024*1024)throw Error('Escolha PNG, JPG ou WebP de até 4 MB.');const result=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});ch().portrait=result;save();render()}catch(e){toast(e.message)}e.target.value=''});
window.addEventListener('beforeunload',()=>{if(!window.desktop&&!storageBlocked){try{localStorage.setItem('forja-3det',JSON.stringify(persisted()))}catch{}}else flushSave()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();flushSave().then(()=>toast('Ficha salva.'))}});
async function init(){try{const raw=window.desktop?await desktop.load():JSON.parse(localStorage.getItem('forja-3det')||'null');if(raw&&Array.isArray(raw.characters)&&raw.characters.length){const selected=raw.characters.findIndex(c=>c.id===raw.selected);state.characters=R.validateImport(raw,{preserveIds:true});window.loadedAudit=raw.audit;state.selected=state.characters[Math.max(0,selected)]?.id;if(raw.recovered)toast('Dados recuperados da cópia de segurança automática.')}}catch(e){storageBlocked=true;lastSave='Erro ao ler dados — importe um backup';toast(e.message)}if(!state.characters.length){state.characters=[R.create('Meu primeiro herói')];state.selected=state.characters[0].id}editHistory.restore(window.loadedAudit,state.characters);historyReady=true;render()}
